head.script:
scwin.screenId = "jldfil25050";

///////// 1. 변수 및 선언 영역 /////////

scwin.obj = undefined;

scwin.wrtrptKindSelectedIdx = 0;

scwin.wrtrptSubmitSelectedIdx = 0;

scwin.bas_acntcls_mm = undefined;

scwin.kind_cd = undefined;

scwin.loop = undefined;

scwin.submitKindCD = undefined;


///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
// 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
/**
 * @method
 * @name scwin.init_ctxDefaults
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_ctxDefaults = function () {
    const cds = {"realIdx":"1"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_srchMyWrtrptInfo", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "srchMyWrtrptInfo" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("srchMyWrtrptInfo"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "srchMyWrtrptInfo" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("srchMyWrtrptInfo")))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["isurCd"] ?? ""); } },
        { childId: "ipt_integUsrId", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? ""); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.obj = (document.form || { elements: [] });
        scwin.setDefaultValues();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25050.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)
/**
 * @method
 * @name scwin.init_sessionFill
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_sessionFill = function () {
    const names = ["isurCd","usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil25050' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldfil25050: 진입 키 wrtrptsubmitddadm 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.isOk = String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.isOk !== "undefined" && scwin.isOk !== null ? scwin.isOk : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isOk" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("isOk"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.isOk !== "undefined" && scwin.isOk !== null ? scwin.isOk : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isOk" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("isOk")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.isOk !== "undefined" && scwin.isOk !== null ? scwin.isOk : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isOk" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("isOk"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (typeof scwin.isOk !== "undefined" && scwin.isOk !== null ? scwin.isOk : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "isOk" + " (as-is EL 부재 = 빈값이라 진행합니다)"), "")))(dma_pageContext.get("isOk"))));

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        await scwin.init_rowCopy();
        await scwin.init_conds();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25050.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Modify_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Modify_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Modify_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.modify()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25050.btn_Modify_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.modify
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.modify = async function () {
    /* sdd-asis-lifecycle:begin fn_Modify — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let selectedIdx = 0;
    if (scwin.obj.editGubun.type === 'radio') {
        if (scwin.obj.editGubun.checked === true) {
            selectedIdx = scwin.obj.editGubun.value;
        }
    } else {
        for (let i = 0; i < scwin.obj.editGubun.length; i++) {
            if (scwin.obj.editGubun[i].checked === true) {
                selectedIdx = (i + 1);
                break;
            }
        }
    }
    if (selectedIdx != 0) {
        if (scwin.isEditabled(selectedIdx)) {
            scwin.checkWrtrptKindCd(scwin.getWrtrptKindcdObj(selectedIdx));
            if ($c.util.getComponent("ipt_wrtrptKindCd").getValue() === '') {
                await $c.win.alert('보고서 구분은 반드시 선택해야 합니다.');
                return;
            }
            if ($c.util.getComponent("ipt_wrtrptSubmitSchdlDd").getValue() === '') {
                await $c.win.alert('제출일은 반드시 선택해야 합니다.');
                return;
            }
        } else {
            await $c.win.alert('개별 보고서 제출일 기준 10일 전 까지만 수정할 수 있습니다.\r\n거래소 공시담당자에게 문의하시기 바랍니다.');
            return;
        }
    } else {
        await $c.win.alert('변경할 항목을 먼저 선택 하십시오.');
        return;
    }
    const submitMsg = $c.util.getComponent("ipt_basYy").getValue() + "년 " + $c.util.getComponent("ipt_basAcntclsMm").getValue() + "월 결산기에 대한 '" + $c.util.getComponent("ipt_wrtrptKindText").getValue() + "'의 제출일을 [" + $c.util.getComponent("ipt_wrtrptSubmitSchdlDdText").getValue() + "]로 변경하시겠습니까?";
    if (await $c.win.confirm(submitMsg)) {
        scwin.obj.submit();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isEditabled
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.isEditabled = function (ver) {
    /* sdd-asis-lifecycle:begin isEditabled — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const add10day = scwin.getYYYYMMDDadd10();
    const submitDay = scwin.getWrtrptSubmitSchdlDdObj(ver).options[1].value;
    if (add10day < submitDay) {
        return true;
    } else {
        return false;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getYYYYMMDDadd10
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.getYYYYMMDDadd10 = function () {
    /* sdd-asis-lifecycle:begin getYYYYMMDDadd10 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const date = new Date();
    date.setDate(date.getDate() + 3);
    let month = ((date.getMonth() + 1) + '');
    let days = (date.getDate() + '');
    if (month.length == 1) {
        month = '0' + month;
    }
    if (days.length == 1) {
        days = '0' + days;
    }
    return date.getFullYear() + month + days;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkWrtrptKindCd
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.checkWrtrptKindCd = function (ver) {
    /* sdd-asis-lifecycle:begin checkWrtrptKindCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_wrtrptKindCd").setValue(ver.value);
    const tmpName = ver.name;
    const tmpIdx = tmpName.substring(tmpName.indexOf('_') + 1);
    scwin.wrtrptKindSelectedIdx = ver.selectedIndex;
    if (scwin.wrtrptSubmitSelectedIdx != 0 && scwin.wrtrptKindSelectedIdx != 0) {
        if (isNaN(ver.value)) {
            scwin.setWrtrptSubmitSchdlDdDisabled(tmpIdx, false);
            if (scwin.wrtrptKindSelectedIdx !== scwin.wrtrptSubmitSelectedIdx) {
                scwin.specialValueSetting(tmpIdx, ver);
            } else {
                scwin.defaultValueSetting(tmpIdx, ver.value);
            }
        } else {
            if (scwin.setWrtrptSubmitSchdlDdToDefault(tmpIdx)) {
                scwin.defaultValueSetting(tmpIdx, ver.value);
                scwin.setWrtrptSubmitSchdlDdDisabled(tmpIdx, true);
            }
        }
    } else {
        if (scwin.wrtrptSubmitSelectedIdx == 0) {
            $c.util.getComponent("ipt_wrtrptSubmitSchdlDd").setValue('');
        } else {
            if (scwin.wrtrptKindSelectedIdx == 0) {
                $c.util.getComponent("ipt_wrtrptKindCd").setValue('');
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setWrtrptSubmitSchdlDdToDefault
 * @author Inswave
 * @date 2026. 09. 29
 * @param idx
 * @returns
 * @hidden N
*/
scwin.setWrtrptSubmitSchdlDdToDefault = function (idx) {
    /* sdd-asis-lifecycle:begin setWrtrptSubmitSchdlDdToDefault — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const tmpObj = eval('obj.wrtrptSubmitSchdlDd_' + idx);
    tmpObj.options[scwin.wrtrptKindSelectedIdx].selected = true;
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setWrtrptSubmitSchdlDdDisabled
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver1 ver2
 * @returns
 * @hidden N
*/
scwin.setWrtrptSubmitSchdlDdDisabled = function (ver1, ver2) {
    /* sdd-asis-lifecycle:begin setWrtrptSubmitSchdlDdDisabled — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const tmpObj = eval('obj.wrtrptSubmitSchdlDd_' + ver1);
    tmpObj.disabled = ver2;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.clearAllData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.clearAllData = function () {
    /* sdd-asis-lifecycle:begin clearAllData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_basYy").setValue('');
    $c.util.getComponent("ipt_basAcntclsMm").setValue('');
    $c.util.getComponent("ipt_wrtrptKindCd").setValue('');
    $c.util.getComponent("ipt_beforeWrtrptKindCd").setValue('');
    $c.util.getComponent("ipt_wrtrptSubmitSchdlDd").setValue('');
    $c.util.getComponent("ipt_wrtrptSubmitObjIsuYn").setValue('');
    $c.util.getComponent("ipt_wrtrptStatObjIsuYn").setValue('');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.specialValueSetting
 * @author Inswave
 * @date 2026. 09. 29
 * @param idx ver1
 * @returns
 * @hidden N
*/
scwin.specialValueSetting = function (idx, ver1) {
    /* sdd-asis-lifecycle:begin specialValueSetting — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_basYy").setValue(eval('obj.basYy_' + idx + '.value'));
    $c.util.getComponent("ipt_basAcntclsMm").setValue(eval('obj.basAcntclsMm_' + idx + '.value'));
    $c.util.getComponent("ipt_ldMktTpCd").setValue(eval('obj.ldMktTpCd_' + idx + '.value'));
    $c.util.getComponent("ipt_wrtrptKindCd").setValue(eval('obj.' + ver1.name + '.options[1].value'));
    $c.util.getComponent("ipt_beforeWrtrptKindCd").setValue(ver1.value);
    $c.util.getComponent("ipt_wrtrptKindText").setValue(scwin.getSelectedText(scwin.getWrtrptKindcdObj(idx)));
    $c.util.getComponent("ipt_wrtrptSubmitSchdlDdText").setValue(scwin.getSelectedText(scwin.getWrtrptSubmitSchdlDdObj(idx)));
    $c.util.getComponent("ipt_wrtrptSubmitSchdlDd").setValue(eval('obj.wrtrptSubmitSchdlDd_' + idx + '.value'));
    scwin.yOrNsetting(1);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getSelectedText
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.getSelectedText = function (ver) {
    /* sdd-asis-lifecycle:begin getSelectedText — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    for (let i = 0; i < ver.length; i++) {
        if (ver.options[i].selected) {
            return ver.options[i].text;
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.yOrNsetting
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.yOrNsetting = function (ver) {
    /* sdd-asis-lifecycle:begin yOrNsetting — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_wrtrptSubmitObjIsuYn").setValue('Y');
    if (ver == 0) {
        $c.util.getComponent("ipt_wrtrptStatObjIsuYn").setValue('N');
    } else {
        $c.util.getComponent("ipt_wrtrptStatObjIsuYn").setValue('Y');
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.defaultValueSetting
 * @author Inswave
 * @date 2026. 09. 29
 * @param idx ver1
 * @returns
 * @hidden N
*/
scwin.defaultValueSetting = function (idx, ver1) {
    /* sdd-asis-lifecycle:begin defaultValueSetting — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("ipt_basYy").setValue(eval('obj.basYy_' + idx + '.value'));
    $c.util.getComponent("ipt_basAcntclsMm").setValue(eval('obj.basAcntclsMm_' + idx + '.value'));
    $c.util.getComponent("ipt_ldMktTpCd").setValue(eval('obj.ldMktTpCd_' + idx + '.value'));
    $c.util.getComponent("ipt_wrtrptKindCd").setValue(ver1);
    $c.util.getComponent("ipt_wrtrptKindText").setValue(scwin.getSelectedText(scwin.getWrtrptKindcdObj(idx)));
    $c.util.getComponent("ipt_wrtrptSubmitSchdlDdText").setValue(scwin.getSelectedText(scwin.getWrtrptSubmitSchdlDdObj(idx)));
    $c.util.getComponent("ipt_wrtrptSubmitSchdlDd").setValue(eval('obj.wrtrptSubmitSchdlDd_' + idx + '.value'));
    if (isNaN(ver1)) {
        scwin.yOrNsetting(1);
        $c.util.getComponent("ipt_beforeWrtrptKindCd").setValue(eval('obj.wrtrptKindCd_' + idx + '.options[' + (parseInt(scwin.wrtrptKindSelectedIdx) - 1) + '].value'));
    } else {
        scwin.yOrNsetting(0);
        $c.util.getComponent("ipt_beforeWrtrptKindCd").setValue(eval('obj.wrtrptKindCd_' + idx + '.options[' + (parseInt(scwin.wrtrptKindSelectedIdx) + 1) + '].value'));
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkWrtrptSubmitSchdlDd
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver
 * @returns
 * @hidden N
*/
scwin.checkWrtrptSubmitSchdlDd = function (ver) {
